"""Quarantine store on an encrypted PersistentVolume; messages are purged after the configured days."""

from __future__ import annotations

import json
import time
from pathlib import Path


class Quarantine:
    def __init__(self, path: str) -> None:
        self.root = Path(path)
        self.root.mkdir(parents=True, exist_ok=True)

    def store(self, msg: dict) -> None:
        (self.root / f"{int(time.time())}-{abs(hash(msg['message_id']))}.json").write_text(json.dumps(msg))

    def purge(self, retention_days: int) -> int:
        cutoff = time.time() - retention_days * 86400
        removed = 0
        for f in self.root.glob("*.json"):
            if f.stat().st_mtime < cutoff:
                f.unlink()
                removed += 1
        return removed

from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass

import joblib

MODEL_VERSION = "nb-2026.10"
URL = re.compile(r"https?://\S+")
EMAIL = re.compile(r"[\w.+-]+@[\w-]+\.[\w.]+")


@dataclass
class Verdict:
    action: str  # deliver | tag | quarantine
    spam_probability: float
    model_version: str = MODEL_VERSION


def normalise(subject: str, body: str) -> str:
    """Reduce the message to what the model needs; addresses become placeholders."""
    text = f"{subject}\n{body[:20000]}"
    text = URL.sub(" URLTOKEN ", text)
    return EMAIL.sub(" EMAILTOKEN ", text).lower()


def message_ref(message_id: str) -> str:
    return hashlib.sha256(message_id.encode()).hexdigest()[:24]


class SpamClassifier:
    def __init__(self, path: str, tag_at: float, quarantine_at: float) -> None:
        self.pipeline = joblib.load(path)
        self.tag_at, self.quarantine_at = tag_at, quarantine_at

    def classify(self, subject: str, body: str) -> Verdict:
        p = float(self.pipeline.predict_proba([normalise(subject, body)])[0][1])
        if p >= self.quarantine_at:
            return Verdict("quarantine", p)
        if p >= self.tag_at:
            return Verdict("tag", p)
        return Verdict("deliver", p)

"""Daily quarantine digest e-mail sent to each employee."""

DIGEST_TEMPLATE = """Subject: Your quarantined messages ({count})

The following messages addressed to you were held by SpamShield, ACME's automated filter, which uses
a machine-learning model to classify incoming e-mail. Nothing has been deleted. If a message is not
spam, click "Release" and it will be delivered; your feedback is used to improve the filter.

{rows}

Quarantined messages are removed automatically after 30 days.
"""


def render(count: int, rows: list[str]) -> str:
    return DIGEST_TEMPLATE.format(count=count, rows="\n".join(rows))
